value.outputSchema:
={{ 
  {
    "type": "object",
    "required": [
      "client_criteria",
      "talents",
      "reasoning"
    ],
    "properties": {
      "client_criteria": {
        "type": "array",
        "items": {
          "type": "string"
        },
        "description": "The client's explicit hiring criteria extracted from the job post."
      },
      "talents": {
        "type": "array",
        "minItems": 0,
        "maxItems": 3,
        "items": {
          "type": "object",
          "required": [
            "name",
            "profile_url",
            "how_they_meet"
          ],
          "properties": {
            "name": {
              "type": "string"
            },
            "profile_url": {
              "type": "string",
              "pattern": "^https:\\/\\/(www\\.)?upwork\\.com\\/freelancers\\/~[0-9a-fA-F]{16,18}$",
              "description": "Upwork profile URL validating a standard 16 to 18 character ciphertext format after the tilde."
            },
            "how_they_meet": {
              "type": "string",
              "description": "Per-criterion evidence that this freelancer meets every client criterion."
            }
          }
        }
      },
      "reasoning": {
        "type": "string",
        "minLength": 10
      }
    }
  }
}}
